mapper.select:
/* buyer.mpso.getBuyerDelyReturnList */ SELECT K.*, (K.PO_QTY / DECODE(K.DV_CNT,0, 1, K.DV_CNT)) AS TARGET_QTY, (K.PO_QTY / DECODE(K.DV_CNT,0, 1, K.DV_CNT)) AS ITEM_QTY, (K.PO_QTY / DECODE(K.DV_CNT,0, 1, K.DV_CNT)) * K.UNIT_PRICE AS ITEM_AMT, (K.PO_QTY / DECODE(K.DV_CNT,0, 1, K.DV_CNT)) - K.RET_TARGET_QTY AS RET_POS_QTY FROM ( SELECT PR.BUYER , PR.PR_NO , PR.PR_SEQ , PO.PO_NO , PO.PO_SEQ , GR.GR_NO , GR.GR_SEQ , CR.PERNR AS LEGACY_REQ_USER_ID , KK.USER_NAME_LOC AS REQ_USER_NAME_LOC , KK.USER_ID AS REQ_USER_ID , CR.MATNR AS BUYER_ITEM_NO , PO.BUYER_ITEM_NO AS ORG_BUYER_ITEM_NO , PO.DESCRIPTION , GR.UNIT_PRICE , PH.PO_CREATE_DATE , PO.ADD_DATE , GR.GR_DATE , PR.ADD_USER_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND CODE = PR.ADD_USER_DEPT AND COMPANY_CODE = 'KRCOWA0001') AS ADD_USER_DEPT_NAME , PR.ADD_USER_ID , (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID ) AS LEGACY_ADD_USER_ID , PR.ADD_USER_NAME , GR.ITEM_QTY AS GR_QTY , PO.BYIT_COMORG_CODE , PO.CONTRACT_NO , PO.CONTRACT_SEQ , GR.AR_BILL_FLAG , #{st_zcode} || ',' || CASE WHEN SUBSTR(PR.REMARK, INSTR(PR.REMARK,KK.USER_NAME_LOC) + LENGTH(KK.USER_NAME_LOC) , 1) IS NULL THEN 'N' WHEN SUBSTR(PR.REMARK, INSTR(PR.REMARK,KK.USER_NAME_LOC) + LENGTH(KK.USER_NAME_LOC) , 1) = ',' THEN 'N' ELSE SUBSTR(PR.REMARK, INSTR(PR.REMARK,KK.USER_NAME_LOC) + LENGTH(KK.USER_NAME_LOC) , 1) END AS MG_NOTE , PR.PO_QTY , PR.REF_PR_NO , CR.ZSTATUS AS ZSTATUS , CASE WHEN RR.PR_NO IS NOT NULL THEN '반납' WHEN GR.AR_BILL_FLAG = 'Y' THEN '정산' ELSE '입고' END AS STATUS , CASE WHEN RR.PR_NO IS NOT NULL THEN 'RT' WHEN GR.AR_BILL_FLAG = 'Y' THEN 'JE' ELSE 'GR' END AS STATUS_CODE , RR.PR_NO AS RET_PR_NO , RR.REF_PR_NO AS RET_REF_PR_NO , ABS(NVL(RR.TARGET_QTY,0)) AS RET_TARGET_QTY , CASE WHEN ABS(NVL(RR.TARGET_QTY,0)) = 0 THEN 'N' ELSE 'Y' END AS RET_CHECK , SUM(ABS(NVL(RR.TARGET_QTY,0))) OVER (PARTITION BY PR.BUYER, PR.PR_NO, PR.PR_SEQ ) AS TOT_RR_QTY , RR.REMARK , (SELECT COUNT(*) FROM COWAY_REQ_STATUS_DISPLAY WHERE BUYER = PR.BUYER AND PR_NO = PR.PR_NO AND PR_SEQ = PR.PR_SEQ) AS DV_CNT FROM ICOMGRDT GR INNER JOIN ICOMPODT PO ON (1 = 1 AND PO.BUYER = GR.BUYER AND PO.PO_NO = GR.PO_NO AND PO.PO_SEQ = GR.PO_SEQ
AND PO.ADD_DATE BETWEEN #{st_from_date } AND #{st_to_date }
AND PO.STATUS IN ('C','R') ) INNER JOIN ICOMPRDT PR ON (1 = 1 AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND PR.STATUS IN ('C','R')
AND PR.REF_PR_NO = #{st_pr_no }
AND PR.ADD_USER_DEPT = #{st_add_user_dept_code }
) INNER JOIN COWAY_REQ_STATUS_DISPLAY CR ON (1 = 1 AND CR.BUYER = PR.BUYER AND CR.PR_NO = PR.PR_NO AND CR.PR_SEQ = PR.PR_SEQ AND CR.MBLNR = PR.REF_PR_NO AND CR.BUYER_ITEM_NO = PR.BUYER_ITEM_nO
AND CR.PERNR LIKE UPPER(#{st_req_legacy_user_id })||'%'
AND CASE WHEN (SELECT POSITION FROM ICOMLUSR WHERE USER_ID = #{st_user_id}) IS NULL AND CR.PERNR = SUBSTR(#{st_user_id}, 3) THEN 'Y' WHEN (SELECT POSITION FROM ICOMLUSR WHERE USER_ID = #{st_user_id}) IS NOT NULL THEN 'Y' ELSE 'N' END = 'Y'
AND (CR.ORGEH = #{st_dept} OR #{st_dept} IN (SELECT DEPT_CODE FROM COWAY_HR_ORGDATA WHERE UP_DEPT_CODE = CR.ORGEH))
) INNER JOIN ICOMLUSR KK ON (1 = 1 AND KK.COM_CODE = PR.BUYER AND KK.LEGACY_USER_ID = CR.PERNR
AND UPPER(KK.USER_NAME_LOC) LIKE UPPER(#{st_req_user_name })||'%'
) LEFT OUTER JOIN ICOMPRDT RR ON (1 = 1 AND RR.BUYER = PR.BUYER AND RR.ORI_PR_NO = PR.PR_NO AND RR.ORI_PR_SEQ = PR.PR_SEQ AND RR.STATUS IN ('C','R') AND RR.RECV_FLAG NOT IN ('RR','PR') ) INNER JOIN ICOMPOHD PH ON (1 = 1 AND PH.BUYER = PO.BUYER AND PH.PO_NO = PO.PO_NO
AND PH.PO_CREATE_DATE BETWEEN #{st_from_date } AND #{st_to_date }
) WHERE 1=1 AND GR.BUYER = #{st_buyer } AND GR.ITEM_QTY > 0 AND GR.STATUS IN ('C','R') AND EXISTS ( SELECT 'X' FROM COWAY_BYIT WHERE ZCODE = #{st_zcode} AND MATNR = GR.BUYER_ITEM_NO AND RECHK = 'Y' ) ) K WHERE 1 = 1
AND K.STATUS_CODE = #{st_status }
ORDER BY REF_PR_NO, BUYER_ITEM_NO, LEGACY_REQ_USER_ID

mapper.update:

/* buyer.mpso.delyReturnTrxlUpdate */
UPDATE EAI.IF_COWAY_PR_SEND
   SET IF_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
       IF_TIME = TO_CHAR(SYSDATE, 'HH24MISS'),
       IF_FLAG = 'Y',
       IF_MSG  = #{MESSAGE }
 WHERE BUYER   = #{BUYER }
   AND PR_NO   = #{PR_NO }
   AND I_MBLNR = #{I_REMBLNR }

