/*buyer.mpso.getOrderNo*/
SELECT DOC_TYPE||SUBSTR(YEAR,3,2)||LPAD(CUR_NO,6,0) AS DOC_NO
  FROM ICOMSQMT
 WHERE COMPANY = #{COM_CODE } 
   AND DOC_TYPE = #{DOC_TYPE }

