/*buyer.mpso.insertSqmt*/
INSERT INTO ICOMSQMT (
	   COMPANY
	 , DOC_TYPE
	 , YEAR
	 , CUR_NO
   ) 
   VALUES 
   (
	   #{COM_CODE }
	 , #{DOC_TYPE }
	 , TO_CHAR(SYSDATE, 'YYYY')
	 , 2
   )


		/*buyer.mpso.updateSqmt*/
		UPDATE ICOMSQMT
		   SET YEAR = DECODE(YEAR, TO_CHAR(SYSDATE, 'YYYY'), YEAR, TO_CHAR(SYSDATE, 'YYYY'))
 			 , CUR_NO = DECODE(YEAR, TO_CHAR(SYSDATE, 'YYYY'), CUR_NO + 1, 1) 
		 WHERE COMPANY = #{COM_CODE } 
		   AND DOC_TYPE = #{DOC_TYPE }
